function fmtBytes(v){const n=Number(v);if(!Number.isFinite(n)||n<0)return '—';const u=['B','KiB','MiB','GiB','TiB'];let x=n,i=0;while(x>=1024&&i<u.length-1){x/=1024;i++}return `${x>=10||i===0?x.toFixed(0):x.toFixed(1)} ${u[i]}`}
