function logEntries(data){return Array.isArray(data?.entries)?data.entries:[]}
function renderLogEntries(data){const rows=logEntries(data);$('logs-summary').textContent=`${Number(data?.count??rows.length)||0} lines${data?.truncated?' · truncated':''}`;$('logs-meta').textContent=[data?.level&&`Threshold ${data.level}`,data?.refreshedAt&&`Refreshed ${data.refreshedAt}`,data?.readError&&'Backend reported a bounded log read warning.'].filter(Boolean).join(' · ');$('logs-output').innerHTML=rows.length?rows.map(x=>`<div class="log-line"><span class="log-level ${escapeText(x.level||'')}">${escapeText(x.level||'—')}</span><span>${escapeText(x.line||'')}</span></div>`).join(''):'<p class="muted">No matching log entries.</p>'}
