async function refreshLogs(){const name=$('logs-name').value;if(!name)return;$('logs-summary').textContent='Loading';try{const env=await listLogs(name,$('logs-tail').value,$('logs-level').value);renderLogEntries(dataOf(env))}catch(e){$('logs-summary').textContent='Unavailable';$('logs-output').innerHTML=`<p class="notice danger-notice">${diagnosticFailure(e,'Unable to read the bounded backend log.')}</p>`}}
const PRIVATE_DOCTOR_CHECKS=new Set(['log_file','host_chroot_root','host_log_file_dir','host_database_dir']);
function renderDoctor(rows){const checks=Array.isArray(rows)?rows:[];const fail=checks.filter(x=>String(x.result).toUpperCase()==='FAIL').length,warn=checks.filter(x=>String(x.result).toUpperCase()==='WARN').length;$('doctor-summary').textContent=fail?`${fail} failed`:warn?`${warn} warnings`:'All passed';$('doctor-output').innerHTML=checks.length?checks.map(x=>{const result=String(x.result||'UNKNOWN').toUpperCase(),privatePath=PRIVATE_DOCTOR_CHECKS.has(String(x.check||'')),detail=privatePath?'Backend path readiness checked without exposing the private filesystem location.':x.detail,next=privatePath&&x.next?'Fix the backend path permissions from the host/CLI, then run doctor again.':x.next;return `<article class="diagnostic-check"><header><strong>${escapeText(x.check)}</strong><span class="${escapeText(result)}">${escapeText(result)}</span></header><p>${escapeText(detail)}</p>${next?`<p><strong>Next:</strong> ${escapeText(next)}</p>`:''}</article>`}).join(''):'<p class="muted">No doctor checks returned.</p>'}
