async function refreshRuntimeDiagnostics(){const results=await Promise.allSettled([invoke('version'),systemRuntime(),moduleStatus(),rcloneStatus()]),version=results[0].status==='fulfilled'?dataOf(results[0].value):null,runtime=results[1].status==='fulfilled'?dataOf(results[1].value):null,module=results[2].status==='fulfilled'?dataOf(results[2].value):null,rclone=results[3].status==='fulfilled'?dataOf(results[3].value):null,life=runtime?.lifecycle||{},remotes=Array.isArray(rclone?.remotes)?rclone.remotes:[],facts=[settingFact('Backend version',version?.version||version?.backend_version||life?.backend?.version||'unavailable'),settingFact('Control mode',life?.mode?.label||life?.state||'unavailable'),settingFact('Module',module?moduleVersionLabel(module):'unavailable'),settingFact('Module runtime',module?.ready?'Ready':'Not ready'),settingFact('Rclone',rclone?.available?`${rclone.version||'available'} · ${remotes.length} remote${remotes.length===1?'':'s'}`:'Unavailable')];$('logs-runtime-facts').innerHTML=facts.join('');const failures=results.filter(x=>x.status==='rejected').length;$('logs-runtime-state').textContent=failures?`${failures} unavailable`:'Checked';$('logs-runtime-state').className=`badge ${failures?'error-badge':'ready-badge'}`}
async function copyDiagnosticText(id,label){const value=$(id)?.innerText?.trim()||'';if(!value){toast(`No ${label} text to copy`);return}try{if(!navigator.clipboard?.writeText)throw new Error('Clipboard API unavailable');await navigator.clipboard.writeText(value);toast(`${label} copied`)}catch(_){toast(`Clipboard unavailable; select the ${label.toLowerCase()} text manually`)}}
async function refreshOperationLogList(){try{const r=await listOperations(50),rows=operationRows(r),previous=$('operation-log-id').value;$('operation-log-id').innerHTML=rows.length?rows.map(x=>`<option value="${escapeText(x.operationId)}">${escapeText(x.title||x.kind||x.operationId)} · ${escapeText(x.state||'unknown')}</option>`).join(''):'<option value="">No recent operations</option>';if(rows.some(x=>x.operationId===previous))$('operation-log-id').value=previous;$('operation-log-refresh').disabled=!rows.length;if(rows.length)await refreshOperationEvents();else{$('operation-log-summary').textContent='No operations';$('operation-log-output').innerHTML='<p class="muted">No persistent operation events are available.</p>'}}catch(e){$('operation-log-summary').textContent='Unavailable';$('operation-log-output').innerHTML=`<p class="notice danger-notice">${diagnosticFailure(e,'Unable to load persistent operation events.')}</p>`}}
