function stopLogsFollow(){if(logsFollowTimer){clearInterval(logsFollowTimer);logsFollowTimer=null}}
function syncLogsFollow(){stopLogsFollow();if(currentSection==='logs'&&$('logs-follow')?.checked){logsFollowTimer=setInterval(()=>{if(currentSection!=='logs')return;refreshLogs();refreshOperationEvents();if($('service-name').value)refreshServiceJournal()},3000)}}
async function loadLogsSection(){if(!isAvailable())return;try{const rows=records(dataOf(await invoke('chrootsList'))),previous=$('logs-name').value;$('logs-name').innerHTML=rows.map(x=>`<option value="${escapeText(x.name)}">${escapeText(x.name)}</option>`).join('');if(rows.some(x=>x.name===previous))$('logs-name').value=previous;else{const preferred=preferredChrootName(rows);if(preferred)$('logs-name').value=preferred}await Promise.all([refreshRuntimeDiagnostics(),refreshOperationLogList()]);if(!rows.length){$('logs-summary').textContent='No chroots';$('doctor-summary').textContent='Not available';$('service-summary').textContent='No chroots';syncLogsFollow();return}await Promise.all([refreshLogs(),refreshDoctor(),refreshServices()]);syncLogsFollow()}catch(e){$('logs-summary').textContent='Unavailable';err(e)}}
$('logs-name').addEventListener('change',()=>{refreshLogs();refreshDoctor();refreshServices()});$('logs-level').addEventListener('change',refreshLogs);$('logs-tail').addEventListener('change',refreshLogs);$('logs-refresh').addEventListener('click',refreshLogs);$('logs-copy').addEventListener('click',()=>copyDiagnosticText('logs-output','Log'));$('logs-follow').addEventListener('change',syncLogsFollow);$('doctor-refresh').addEventListener('click',refreshDoctor);$('service-refresh').addEventListener('click',refreshServiceJournal);$('service-copy').addEventListener('click',()=>copyDiagnosticText('service-output','Service journal'));$('operation-log-id').addEventListener('change',refreshOperationEvents);$('operation-log-refresh').addEventListener('click',refreshOperationEvents);$('operation-log-copy').addEventListener('click',()=>copyDiagnosticText('operation-log-output','Operation events'));

